+function traitKey(config: ConfigurableTrait | Trait | RelationPair) {
+    if (isRelationPair(config)) {
+        const pair = config[$internal];
+        return `${pair.relation[$internal].trait.id}:${String(pair.target)}`;
+    }
+    const trait = Array.isArray(config) ? config[0] : config;
