+function enqueue(world: World, command: DeferredCommand) {
+    const commands = scope(world);
+    // A later value for an already-pending addition is the value that gets applied.
+    if (command.type === 'add' || command.type === 'addExclusive') {
+        for (let i = commands.length - 1; i >= 0; i--) {
+            const previous = commands[i];
+            if (previous.entity !== command.entity) continue;
+            if (previous.type === 'destroy' || previous.type === 'remove') break;
+            if (previous.type !== 'add' && previous.type !== 'addExclusive') continue;
+            for (const config of command.traits) {
+                const key = traitKey(config);
+                const at = previous.traits.findIndex((item) => traitKey(item) === key);
+                if (at >= 0) previous.traits[at] = config;
+                else previous.traits.push(config);
