+export function deferredHas(world: World, entity: Entity, trait: Trait | RelationPair): boolean | undefined {
+    const commands = world[$internal].deferred.scopes.flat();
+    if (!commands.some((command) => command.entity === entity)) return undefined;
+    let alive = isEntityAlive(world[$internal].entityIndex, entity) || commands.some((c) => c.type === 'spawn' && c.entity === entity);
+    let value = isRelationPair(trait) ? hasRelationPair(world, entity, trait) : hasTrait(world, entity, trait);
+    for (const command of commands) {
+        if (command.entity !== entity) continue;
+        if (command.type === 'destroy') { alive = false; value = false; continue; }
+        if (command.type === 'spawn') { alive = true; continue; }
+        if (!alive) continue;
+        if (command.type === 'remove' && command.traits.some((item) => traitKey(item) === traitKey(trait))) value = false;
+        if ((command.type === 'add' || command.type === 'addExclusive') && command.traits.some((item) => traitKey(item) === traitKey(trait))) value = true;
+        if (command.type === 'addExclusive' && isRelationPair(trait)) {
+            const relation = trait[$internal].relation;
+            if (command.traits.some((item) => isRelationPair(item) && item[$internal].relation === relation)) {
